CREATE TABLE users (id BIGINT IDENTITY PRIMARY KEY, full_name NVARCHAR(150) NOT NULL, email NVARCHAR(255) NOT NULL UNIQUE, password_hash NVARCHAR(255) NOT NULL, language NVARCHAR(10) NOT NULL DEFAULT 'vi', created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE roles (id BIGINT IDENTITY PRIMARY KEY, name NVARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, CONSTRAINT pk_user_roles PRIMARY KEY(user_id, role_id), CONSTRAINT fk_ur_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_ur_role FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE products (id BIGINT IDENTITY PRIMARY KEY, name NVARCHAR(255) NOT NULL, slug NVARCHAR(255) NOT NULL UNIQUE, description NVARCHAR(MAX), price DECIMAL(18,2) NOT NULL, thumbnail_url NVARCHAR(500), status NVARCHAR(30) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE locations (id BIGINT IDENTITY PRIMARY KEY, name NVARCHAR(255) NOT NULL, slug NVARCHAR(255) NOT NULL UNIQUE, description NVARCHAR(MAX), image_url NVARCHAR(500));
CREATE TABLE stories (id BIGINT IDENTITY PRIMARY KEY, location_id BIGINT NULL, title NVARCHAR(255) NOT NULL, slug NVARCHAR(255) NOT NULL UNIQUE, summary NVARCHAR(1000), content NVARCHAR(MAX), category NVARCHAR(50), cover_image NVARCHAR(500), reading_time INT, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), CONSTRAINT fk_story_location FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE digital_passports (id BIGINT IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, total_points INT NOT NULL DEFAULT 0, level INT NOT NULL DEFAULT 1, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), CONSTRAINT fk_passport_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE qr_tokens (id BIGINT IDENTITY PRIMARY KEY, token NVARCHAR(255) NOT NULL UNIQUE, product_id BIGINT NULL, status NVARCHAR(30) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), used_at DATETIME2 NULL, expires_at DATETIME2 NULL, CONSTRAINT fk_qr_product FOREIGN KEY(product_id) REFERENCES products(id));
